def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]

    def components(cells):
        cells = set(cells)
        result = []
        while cells:
            start = cells.pop()
            stack = [start]
            comp = {start}
            while stack:
                y, x = stack.pop()
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    p = (y + dy, x + dx)
                    if p in cells:
                        cells.remove(p)
                        comp.add(p)
                        stack.append(p)
            result.append(comp)
        return result

    objects = []
    unseen = {(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg}
    for comp in components(unseen):
        r = next(iter(comp))[0]
        c = next(p[1] for p in comp if p[0] == r)
        objects.append((grid[r][c], comp))

    def normalized(cells):
        y0 = min(y for y, x in cells)
        x0 = min(x for y, x in cells)
        return frozenset((y - y0, x - x0) for y, x in cells)

    for color, cells in objects:
        y0 = min(y for y, x in cells)
        y1 = max(y for y, x in cells)
        x0 = min(x for y, x in cells)
        x1 = max(x for y, x in cells)
        holes = components((y, x) for y in range(y0, y1 + 1)
                           for x in range(x0, x1 + 1) if (y, x) not in cells)
        if not holes:
            continue

        remaining = objects.copy()
        remaining.remove((color, cells))
        assignments = []
        possible = True
        for hole in holes:
            shape = normalized(hole)
            match = next(((mc, mc_cells) for mc, mc_cells in remaining
                          if normalized(mc_cells) == shape), None)
            if match is None:
                possible = False
                break
            assignments.append((hole, match[0]))
            remaining.remove(match)
        if not possible:
            continue

        out = [[bg] * (x1 - x0 + 1) for _ in range(y1 - y0 + 1)]
        for y, x in cells:
            out[y - y0][x - x0] = color
        for hole, marker_color in assignments:
            for y, x in hole:
                out[y - y0][x - x0] = marker_color
        return out

    return grid
